class Animal:
    pass


class Dog(Animal):
    def __init__(self, name):
        self.name = name


class Cat(Animal):
    def __init__(self, name):
        self.name = name


class Person:
    def __init__(self, name):
        self.name = name
        self.pet = None  # has-a pet (maybe)


class Employee(Person):
    def __init__(self, name, salary):
        super().__init__(name)
        self.salary = salary


rover = Dog("Rover")
satan = Cat("Satan")
mary = Person("Mary")
mary.pet = satan
frank = Employee("Frank", 120000)
frank.pet = rover

print("Dog is-a Animal?", isinstance(rover, Animal))
print("Mary has-a pet:", mary.pet.name)
print("Frank is-a Person?", isinstance(frank, Person))
print("Frank has-a pet:", frank.pet.name, "salary:", frank.salary)
